create extension if not exists pgcrypto;
create extension if not exists citext;
create extension if not exists pg_trgm;

create type tenant_type_enum as enum ('platform','practice','billing_company','facility');
create type tenant_status_enum as enum ('active','inactive','suspended','terminated','pending_setup');
create type user_status_enum as enum ('active','inactive','invited','suspended','terminated');
create type system_role_enum as enum ('platform_admin','practice_admin','billing_company_admin','billing_manager','biller','clinician','front_desk','credentialing_specialist','read_only','client');
create type client_status_enum as enum ('active','inactive','intake','waitlist','discharged','deceased','archived');
create type registration_status_enum as enum ('not_started','in_progress','pending_review','complete','needs_correction','archived');
create type billing_readiness_status_enum as enum ('not_ready','missing_insurance','missing_diagnosis','missing_authorization','missing_signed_note','ready_for_charge','ready_for_claim');
create type insurance_policy_status_enum as enum ('active','inactive','pending_verification','terminated','unknown');
create type insurance_order_enum as enum ('primary','secondary','tertiary','other');
create type eligibility_status_enum as enum ('active','inactive','eligible','ineligible','coverage_terminated','unable_to_verify','pending','error');
create type authorization_status_enum as enum ('not_required','pending','approved','denied','expired','exhausted','cancelled','unknown');
create type appointment_status_enum as enum ('scheduled','confirmed','client_on_my_way','client_arrived','checked_in','in_session','completed','cancelled','no_show','late_cancel','rescheduled');
create type appointment_location_type_enum as enum ('in_person','telehealth','phone','community','home','school','other');
create type clinical_note_status_enum as enum ('draft','in_progress','ready_for_signature','signed','locked','amended','voided');
create type clinical_note_type_enum as enum ('psychotherapy','assessment','intake','treatment_plan','treatment_plan_review','crisis','case_management','group','collateral','peer_support','medication_management','administrative','other');
create type treatment_plan_status_enum as enum ('draft','active','under_review','expired','discontinued','superseded','signed');
create type diagnosis_status_enum as enum ('active','rule_out','resolved','inactive','entered_in_error');
create type charge_status_enum as enum ('captured','ready_for_claim','claim_created','blocked','voided','patient_responsibility');
create type claim_status_enum as enum ('ready_for_validation','validation_failed','ready_for_batch','batched','submitted','accepted','rejected','denied','partially_paid','paid','appealed','corrected','voided','reversed','patient_responsibility');
create type claim_batch_status_enum as enum ('created','validating','ready','downloaded','submitted','accepted','rejected','partially_accepted','voided');
create type submission_status_enum as enum ('created','submitted','accepted','rejected','failed','pending_response','resubmitted','cancelled');
create type payment_status_enum as enum ('pending','posted','partially_applied','unapplied','reversed','voided','refunded');
create type payment_source_enum as enum ('insurance','patient','third_party','historical','transfer','refund','adjustment','other');
create type payment_method_enum as enum ('eft','ach','check','credit_card','debit_card','cash','money_order','portal','manual','other');
create type adjustment_status_enum as enum ('pending','posted','reversed','voided');
create type adjustment_type_enum as enum ('contractual','payer_writeoff','patient_writeoff','credentialing_writeoff','timely_filing_writeoff','bad_debt','refund_correction','balance_correction','recoupment','other');
create type historical_transaction_type_enum as enum ('payment','adjustment','opening_balance','credit','refund','transfer','correction');
create type historical_transaction_status_enum as enum ('draft','posted','linked','partially_linked','reversed','voided');
create type ledger_entry_type_enum as enum ('charge','insurance_payment','patient_payment','adjustment','writeoff','refund','credit','transfer','opening_balance','reversal','recoupment','correction');
create type ledger_account_type_enum as enum ('asset','liability','revenue','expense','contra_revenue','receivable','adjustment','equity');
create type ledger_side_enum as enum ('debit','credit');
create type accounting_period_status_enum as enum ('open','closed','locked','reopened');
create type era_file_status_enum as enum ('uploaded','parsed','matched','partially_matched','posted','failed','voided');
create type era_match_status_enum as enum ('unmatched','matched','partially_matched','ambiguous','posted','ignored');
create type denial_status_enum as enum ('new','reviewing','workable','non_workable','appealed','corrected_claim_needed','reconsideration_needed','resolved_paid','resolved_writeoff','upheld','closed');
create type denial_category_enum as enum ('eligibility','authorization','credentialing','contracting','coding','documentation','timely_filing','medical_necessity','coordination_of_benefits','duplicate','benefit_limit','patient_responsibility','payer_processing_error','other');
create type denial_workability_enum as enum ('workable','non_workable','needs_review','auto_writeoff');
create type appeal_status_enum as enum ('not_started','drafting','submitted','pending','approved','denied','partially_approved','withdrawn','closed');
create type workqueue_status_enum as enum ('open','in_progress','pending','snoozed','completed','cancelled','reopened');
create type workqueue_priority_enum as enum ('low','normal','high','urgent');
create type workqueue_source_object_type_enum as enum ('client','appointment','charge','claim','claim_batch','authorization','eligibility','payment','adjustment','historical_transaction','era','denial','appeal','ledger_entry','provider','payer_contract');
create type workqueue_type_enum as enum ('eligibility_issue','authorization_issue','missing_documentation','charge_validation','claim_validation','claim_rejection','denial_followup','appeal_deadline','ar_followup','payment_posting_issue','unmatched_era','overpayment_review','credit_balance_review','refund_review','credentialing_issue','contract_variance','patient_balance_review','import_error','sync_error','general_task');
create type note_type_enum as enum ('account','claim','payment','authorization','eligibility','clinical','admin','workqueue','general');
create type note_visibility_enum as enum ('internal','client_visible','provider_visible','billing_only','admin_only');
create type provider_status_enum as enum ('active','inactive','pending','terminated','on_leave');
create type provider_enrollment_status_enum as enum ('not_started','in_progress','submitted','approved','denied','terminated','expired','needs_revalidation','unknown');
create type contract_status_enum as enum ('draft','active','pending','expired','terminated','superseded');
create type document_type_enum as enum ('insurance_card','intake_form','consent_form','clinical_note','treatment_plan','assessment','authorization_letter','eob','era','appeal_letter','payer_correspondence','client_correspondence','claim_attachment','invoice','statement','other');
create type document_status_enum as enum ('uploaded','pending_review','approved','rejected','archived','voided');

create table tenants (id uuid primary key default gen_random_uuid(), name text not null, tenant_type tenant_type_enum not null default 'practice', status tenant_status_enum not null default 'pending_setup', timezone text not null default 'America/Denver', settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table user_profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text, last_name text, display_name text, email citext, phone text, status user_status_enum not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table tenant_users (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, status user_status_enum not null default 'active', invited_at timestamptz, joined_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (tenant_id, user_id));
create table tenant_user_roles (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role system_role_enum not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (tenant_id, user_id, role));
create table billing_company_practice_links (id uuid primary key default gen_random_uuid(), billing_company_tenant_id uuid not null references tenants(id) on delete cascade, practice_tenant_id uuid not null references tenants(id) on delete cascade, status tenant_status_enum not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (billing_company_tenant_id, practice_tenant_id));
create table audit_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id) on delete set null, actor_id uuid references auth.users(id) on delete set null, action text not null, target_type text not null, target_id text, old_values jsonb, new_values jsonb, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table status_history (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id) on delete set null, target_type text not null, target_id uuid not null, old_status text, new_status text not null, changed_by uuid references auth.users(id) on delete set null, reason text, created_at timestamptz not null default now());
create table system_events (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id) on delete set null, event_type text not null, source_type text, source_id uuid, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table phi_access_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id) on delete set null, client_id uuid, user_id uuid references auth.users(id) on delete set null, access_reason text, target_type text, target_id uuid, accessed_at timestamptz not null default now());
create table payers (id uuid primary key default gen_random_uuid(), name text not null, normalized_name text generated always as (lower(regexp_replace(name, '\s+', ' ', 'g'))) stored, payer_type text, clearinghouse_payer_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table payer_plans (id uuid primary key default gen_random_uuid(), payer_id uuid not null references payers(id) on delete cascade, name text not null, plan_type text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table payer_aliases (id uuid primary key default gen_random_uuid(), payer_id uuid not null references payers(id) on delete cascade, alias text not null, source text, created_at timestamptz not null default now(), unique (payer_id, alias));
create table clients (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, first_name text not null, middle_name text, last_name text not null, preferred_name text, date_of_birth date, email citext, phone text, address_line1 text, address_line2 text, city text, state text, postal_code text, client_status client_status_enum not null default 'intake', registration_status registration_status_enum not null default 'not_started', billing_readiness_status billing_readiness_status_enum not null default 'not_ready', search_name text generated always as (lower(coalesce(first_name,'') || ' ' || coalesce(last_name,'') || ' ' || coalesce(preferred_name,'') || ' ' || coalesce(email::text,'') || ' ' || coalesce(phone,''))) stored, metadata jsonb not null default '{}'::jsonb, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table phi_access_logs add constraint phi_access_logs_client_id_fkey foreign key (client_id) references clients(id) on delete set null;
create table client_contacts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, contact_name text not null, relationship text, phone text, email citext, is_emergency_contact boolean not null default false, is_responsible_party boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table client_insurance_policies (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, payer_id uuid not null references payers(id), payer_plan_id uuid references payer_plans(id), insurance_order insurance_order_enum not null default 'primary', status insurance_policy_status_enum not null default 'pending_verification', member_id text not null, group_number text, subscriber_name text, subscriber_dob date, relationship_to_subscriber text default 'self', effective_date date, termination_date date, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (termination_date is null or effective_date is null or termination_date >= effective_date));
create table eligibility_checks (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, insurance_policy_id uuid references client_insurance_policies(id) on delete set null, payer_id uuid references payers(id), service_date date not null, eligibility_status eligibility_status_enum not null default 'pending', checked_by uuid references auth.users(id) on delete set null, response_source text, raw_response jsonb, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table eligibility_benefits (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, eligibility_check_id uuid not null references eligibility_checks(id) on delete cascade, benefit_type text not null, cpt_code text, copay_cents bigint, coinsurance_percent numeric(5,2), deductible_remaining_cents bigint, oop_remaining_cents bigint, authorization_required boolean, network_status text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table providers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, first_name text not null, last_name text not null, credentials text, provider_status provider_status_enum not null default 'active', individual_npi text, taxonomy_code text, email citext, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table provider_identifiers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, provider_id uuid not null references providers(id) on delete cascade, identifier_type text not null, identifier_value text not null, payer_id uuid references payers(id), effective_date date, termination_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table provider_payer_enrollments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, provider_id uuid not null references providers(id) on delete cascade, payer_id uuid not null references payers(id), enrollment_status provider_enrollment_status_enum not null default 'not_started', effective_date date, termination_date date, payer_provider_id text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (provider_id, payer_id));
create table appointments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, provider_id uuid references providers(id) on delete set null, starts_at timestamptz not null, ends_at timestamptz not null, appointment_status appointment_status_enum not null default 'scheduled', location_type appointment_location_type_enum not null default 'telehealth', service_type text, cpt_code text, notes text, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_at > starts_at));
create table client_checkins (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, appointment_id uuid not null references appointments(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, on_my_way_at timestamptz, arrived_at timestamptz, checked_in_at timestamptz, responses jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (appointment_id));
create table client_diagnoses (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, diagnosis_code text not null, description text, diagnosis_status diagnosis_status_enum not null default 'active', onset_date date, resolved_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table treatment_plans (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, provider_id uuid references providers(id) on delete set null, status treatment_plan_status_enum not null default 'draft', effective_date date, review_due_date date, signed_at timestamptz, plan_text text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table treatment_plan_goals (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, treatment_plan_id uuid not null references treatment_plans(id) on delete cascade, goal_text text not null, objective_text text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table clinical_notes (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, appointment_id uuid references appointments(id) on delete set null, provider_id uuid references providers(id) on delete set null, treatment_plan_id uuid references treatment_plans(id) on delete set null, note_type clinical_note_type_enum not null default 'psychotherapy', note_status clinical_note_status_enum not null default 'draft', service_date date, start_time time, end_time time, duration_minutes integer, cpt_code text, diagnosis_code text, goal_addressed text, note_text text, locked_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table clinical_note_signatures (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, clinical_note_id uuid not null references clinical_notes(id) on delete cascade, signer_id uuid not null references auth.users(id) on delete restrict, signed_at timestamptz not null default now(), signature_text text, created_at timestamptz not null default now(), unique (clinical_note_id, signer_id));
create table authorizations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, payer_id uuid references payers(id), authorization_number text, status authorization_status_enum not null default 'pending', start_date date, end_date date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (end_date is null or start_date is null or end_date >= start_date));
create table authorization_units (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, authorization_id uuid not null references authorizations(id) on delete cascade, cpt_code text, authorized_units numeric(10,2) not null default 0, used_units numeric(10,2) not null default 0, remaining_units numeric(10,2) generated always as (authorized_units - used_units) stored, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (authorized_units >= 0 and used_units >= 0));
create table charge_capture_items (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, appointment_id uuid references appointments(id) on delete set null, clinical_note_id uuid references clinical_notes(id) on delete set null, provider_id uuid references providers(id) on delete set null, payer_id uuid references payers(id), service_date date not null, cpt_code text not null, modifier1 text, modifier2 text, diagnosis_code text, place_of_service text, charge_amount_cents bigint not null default 0, charge_status charge_status_enum not null default 'captured', block_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table professional_claims (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, charge_id uuid references charge_capture_items(id) on delete set null, client_id uuid not null references clients(id) on delete cascade, rendering_provider_id uuid references providers(id) on delete set null, billing_provider_id uuid references providers(id) on delete set null, payer_id uuid references payers(id), claim_status claim_status_enum not null default 'ready_for_validation', service_date_from date, service_date_to date, total_charge_cents bigint not null default 0, patient_control_number text, payer_claim_number text, clearinghouse_claim_id text, submitted_at timestamptz, accepted_at timestamptz, paid_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table professional_claim_lines (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, claim_id uuid not null references professional_claims(id) on delete cascade, service_date date not null, cpt_code text not null, modifier1 text, modifier2 text, diagnosis_pointer text, units numeric(10,2) not null default 1, charge_amount_cents bigint not null default 0, allowed_amount_cents bigint, paid_amount_cents bigint not null default 0, adjustment_amount_cents bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table claim_diagnoses (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, claim_id uuid not null references professional_claims(id) on delete cascade, diagnosis_code text not null, pointer_order integer not null default 1, created_at timestamptz not null default now(), unique (claim_id, diagnosis_code));
create table claim_status_history (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, claim_id uuid not null references professional_claims(id) on delete cascade, old_status claim_status_enum, new_status claim_status_enum not null, reason text, changed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table claim_batches (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, batch_status claim_batch_status_enum not null default 'created', batch_name text, claim_count integer not null default 0, total_charge_cents bigint not null default 0, submitted_at timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table claim_batch_items (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, batch_id uuid not null references claim_batches(id) on delete cascade, claim_id uuid not null references professional_claims(id) on delete cascade, created_at timestamptz not null default now(), unique (batch_id, claim_id));
create table claim_submissions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, batch_id uuid references claim_batches(id) on delete set null, claim_id uuid references professional_claims(id) on delete cascade, submission_status submission_status_enum not null default 'created', submission_method text, submitted_at timestamptz, response_payload jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table submission_responses (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, submission_id uuid references claim_submissions(id) on delete cascade, claim_id uuid references professional_claims(id) on delete cascade, response_status submission_status_enum not null, response_code text, response_message text, raw_response jsonb, created_at timestamptz not null default now());
create table payments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid references clients(id) on delete set null, payer_id uuid references payers(id), payment_source payment_source_enum not null, payment_method payment_method_enum not null default 'manual', payment_status payment_status_enum not null default 'pending', payment_date date not null default current_date, amount_cents bigint not null, check_number text, trace_number text, notes text, posted_by uuid references auth.users(id) on delete set null, posted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (amount_cents >= 0));
create table payment_allocations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, payment_id uuid not null references payments(id) on delete cascade, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, claim_line_id uuid references professional_claim_lines(id) on delete set null, amount_cents bigint not null, reversed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (amount_cents >= 0));
create table payment_reversals (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, payment_id uuid not null references payments(id) on delete cascade, reason text not null, reversed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table adjustments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, payer_id uuid references payers(id), adjustment_type adjustment_type_enum not null, adjustment_status adjustment_status_enum not null default 'pending', adjustment_date date not null default current_date, amount_cents bigint not null, reason text, carc_code text, posted_by uuid references auth.users(id) on delete set null, posted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (amount_cents >= 0));
create table adjustment_allocations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, adjustment_id uuid not null references adjustments(id) on delete cascade, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, claim_line_id uuid references professional_claim_lines(id) on delete set null, amount_cents bigint not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (amount_cents >= 0));
create table adjustment_reversals (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, adjustment_id uuid not null references adjustments(id) on delete cascade, reason text not null, reversed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table historical_transactions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, payer_id uuid references payers(id), transaction_type historical_transaction_type_enum not null, transaction_status historical_transaction_status_enum not null default 'draft', transaction_date date not null default current_date, amount_cents bigint not null, description text, legacy_source text, posted_by uuid references auth.users(id) on delete set null, posted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (amount_cents >= 0));
create table historical_transaction_allocations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, historical_transaction_id uuid not null references historical_transactions(id) on delete cascade, claim_id uuid references professional_claims(id) on delete set null, amount_cents bigint not null, created_at timestamptz not null default now(), check (amount_cents >= 0));
create table ledger_accounts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, account_code text not null, account_name text not null, account_type ledger_account_type_enum not null, is_system_account boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (tenant_id, account_code));
create table ledger_transactions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, transaction_date date not null default current_date, source_type text not null, source_id uuid, description text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table ledger_entries (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, ledger_transaction_id uuid not null references ledger_transactions(id) on delete cascade, ledger_account_id uuid references ledger_accounts(id) on delete set null, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, payer_id uuid references payers(id), entry_type ledger_entry_type_enum not null, side ledger_side_enum not null, amount_cents bigint not null, posting_date date not null default current_date, description text, created_at timestamptz not null default now(), check (amount_cents >= 0));
create table client_balance_summaries (client_id uuid primary key references clients(id) on delete cascade, tenant_id uuid not null references tenants(id) on delete cascade, open_balance_cents bigint not null default 0, credit_balance_cents bigint not null default 0, last_calculated_at timestamptz not null default now());
create table claim_balance_summaries (claim_id uuid primary key references professional_claims(id) on delete cascade, tenant_id uuid not null references tenants(id) on delete cascade, total_charge_cents bigint not null default 0, paid_amount_cents bigint not null default 0, adjustment_amount_cents bigint not null default 0, open_balance_cents bigint not null default 0, last_calculated_at timestamptz not null default now());
create table accounting_periods (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, period_name text not null, start_date date not null, end_date date not null, status accounting_period_status_enum not null default 'open', closed_at timestamptz, closed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (end_date >= start_date));
create table era_files (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, payer_id uuid references payers(id), file_name text not null, storage_path text, check_or_trace_number text, payment_amount_cents bigint, status era_file_status_enum not null default 'uploaded', raw_metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table era_claims (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, era_file_id uuid not null references era_files(id) on delete cascade, payer_claim_number text, patient_control_number text, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, charge_amount_cents bigint, paid_amount_cents bigint, status era_match_status_enum not null default 'unmatched', raw_data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table era_service_lines (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, era_claim_id uuid not null references era_claims(id) on delete cascade, claim_line_id uuid references professional_claim_lines(id) on delete set null, service_date date, cpt_code text, charge_amount_cents bigint, paid_amount_cents bigint, raw_data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table era_adjustments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, era_claim_id uuid references era_claims(id) on delete cascade, era_service_line_id uuid references era_service_lines(id) on delete cascade, group_code text, carc_code text, rarc_code text, amount_cents bigint not null default 0, created_at timestamptz not null default now());
create table era_matches (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, era_claim_id uuid not null references era_claims(id) on delete cascade, claim_id uuid references professional_claims(id) on delete set null, match_status era_match_status_enum not null default 'unmatched', confidence numeric(5,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table denials (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, claim_id uuid references professional_claims(id) on delete set null, client_id uuid references clients(id) on delete set null, payer_id uuid references payers(id), denial_date date not null default current_date, denial_status denial_status_enum not null default 'new', denial_category denial_category_enum not null default 'other', workability denial_workability_enum not null default 'needs_review', carc_code text, rarc_code text, amount_cents bigint, reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table appeals (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, denial_id uuid references denials(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, appeal_status appeal_status_enum not null default 'not_started', appeal_level text, deadline_date date, submitted_at timestamptz, outcome text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table workqueue_items (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, workqueue_type workqueue_type_enum not null, workqueue_status workqueue_status_enum not null default 'open', priority workqueue_priority_enum not null default 'normal', source_object_type workqueue_source_object_type_enum not null, source_object_id uuid not null, title text not null, description text, due_date date, assigned_user_id uuid references auth.users(id) on delete set null, created_by uuid references auth.users(id) on delete set null, completed_at timestamptz, completed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table workqueue_history (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, workqueue_item_id uuid not null references workqueue_items(id) on delete cascade, old_status workqueue_status_enum, new_status workqueue_status_enum, old_priority workqueue_priority_enum, new_priority workqueue_priority_enum, changed_by uuid references auth.users(id) on delete set null, note text, created_at timestamptz not null default now());
create table account_notes (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid not null references clients(id) on delete cascade, note_type note_type_enum not null default 'account', visibility note_visibility_enum not null default 'internal', note_text text not null, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table claim_notes (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, claim_id uuid not null references professional_claims(id) on delete cascade, visibility note_visibility_enum not null default 'billing_only', note_text text not null, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table documents (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, client_id uuid references clients(id) on delete set null, claim_id uuid references professional_claims(id) on delete set null, authorization_id uuid references authorizations(id) on delete set null, appeal_id uuid references appeals(id) on delete set null, document_type document_type_enum not null default 'other', document_status document_status_enum not null default 'uploaded', file_name text not null, storage_path text not null, mime_type text, file_size_bytes bigint, uploaded_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table payer_contracts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, payer_id uuid not null references payers(id), contract_name text not null, status contract_status_enum not null default 'draft', effective_date date, termination_date date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (termination_date is null or effective_date is null or termination_date >= effective_date));
create table fee_schedules (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, payer_contract_id uuid references payer_contracts(id) on delete cascade, name text not null, status contract_status_enum not null default 'draft', effective_date date, termination_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table fee_schedule_lines (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, fee_schedule_id uuid not null references fee_schedules(id) on delete cascade, cpt_code text not null, modifier text, rate_cents bigint not null, unit_type text default 'service', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (fee_schedule_id, cpt_code, modifier));
create table import_batches (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, import_name text not null, import_status text not null default 'uploaded', source_system text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table import_rows (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, import_batch_id uuid not null references import_batches(id) on delete cascade, row_number integer not null, raw_data jsonb not null, mapped_data jsonb, row_status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table import_validation_errors (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, import_batch_id uuid not null references import_batches(id) on delete cascade, import_row_id uuid references import_rows(id) on delete cascade, severity text not null default 'error', field_name text, message text not null, created_at timestamptz not null default now());
create table notifications (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, notification_type text not null, title text not null, body text, read_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create or replace function public.is_tenant_member(p_tenant_id uuid) returns boolean language sql stable security definer set search_path = public, auth as $$ select exists (select 1 from public.tenant_users tu where tu.tenant_id = p_tenant_id and tu.user_id = (select auth.uid()) and tu.status = 'active'); $$;
create or replace function public.has_tenant_role(p_tenant_id uuid, p_role system_role_enum) returns boolean language sql stable security definer set search_path = public, auth as $$ select exists (select 1 from public.tenant_user_roles tur join public.tenant_users tu on tu.tenant_id = tur.tenant_id and tu.user_id = tur.user_id where tur.tenant_id = p_tenant_id and tur.user_id = (select auth.uid()) and tur.role = p_role and tu.status = 'active'); $$;
create or replace function public.set_timestamps() returns trigger language plpgsql as $$ begin if tg_op = 'INSERT' then new.created_at = coalesce(new.created_at, now()); new.updated_at = coalesce(new.updated_at, now()); elsif tg_op = 'UPDATE' then new.updated_at = now(); end if; return new; end; $$;
create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path = public, auth as $$ declare v_tenant_id uuid; v_target_id text; begin v_tenant_id := coalesce((to_jsonb(new)->>'tenant_id')::uuid, (to_jsonb(old)->>'tenant_id')::uuid); v_target_id := coalesce(to_jsonb(new)->>'id', to_jsonb(old)->>'id'); insert into public.audit_logs (tenant_id, actor_id, action, target_type, target_id, old_values, new_values) values (v_tenant_id, (select auth.uid()), tg_op, tg_table_name, v_target_id, case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end, case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end); return coalesce(new, old); end; $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public, auth as $$ begin insert into public.user_profiles (id, first_name, last_name, display_name, email) values (new.id, new.raw_user_meta_data ->> 'first_name', new.raw_user_meta_data ->> 'last_name', coalesce(new.raw_user_meta_data ->> 'display_name', new.email), new.email) on conflict (id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.lock_note_after_signature() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.clinical_notes set note_status = 'signed', locked_at = coalesce(locked_at, now()) where id = new.clinical_note_id; return new; end; $$;
create trigger trg_lock_note_after_signature after insert on clinical_note_signatures for each row execute function public.lock_note_after_signature();
create or replace function public.prevent_locked_note_update() returns trigger language plpgsql as $$ begin if old.locked_at is not null and new.note_text is distinct from old.note_text then raise exception 'Locked clinical notes cannot be edited. Create an amendment instead.'; end if; return new; end; $$;
create trigger trg_prevent_locked_note_update before update on clinical_notes for each row execute function public.prevent_locked_note_update();
create or replace function public.create_claim_status_history() returns trigger language plpgsql security definer set search_path = public, auth as $$ begin if new.claim_status is distinct from old.claim_status then insert into public.claim_status_history (tenant_id, claim_id, old_status, new_status, changed_by) values (new.tenant_id, new.id, old.claim_status, new.claim_status, (select auth.uid())); end if; return new; end; $$;
create trigger trg_create_claim_status_history after update on professional_claims for each row execute function public.create_claim_status_history();
create or replace function public.sync_charge_after_claim_created() returns trigger language plpgsql security definer set search_path = public as $$ begin if new.charge_id is not null then update public.charge_capture_items set charge_status = 'claim_created' where id = new.charge_id and charge_status <> 'voided'; end if; return new; end; $$;
create trigger trg_sync_charge_after_claim_created after insert on professional_claims for each row execute function public.sync_charge_after_claim_created();
create or replace function public.recalculate_claim_balance_summary(p_claim_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare v_tenant_id uuid; v_total bigint; v_paid bigint; v_adj bigint; begin select tenant_id, total_charge_cents into v_tenant_id, v_total from public.professional_claims where id = p_claim_id; if v_tenant_id is null then return; end if; select coalesce(sum(amount_cents),0) into v_paid from public.payment_allocations where claim_id = p_claim_id and reversed_at is null; select coalesce(sum(amount_cents),0) into v_adj from public.adjustment_allocations where claim_id = p_claim_id; insert into public.claim_balance_summaries (claim_id, tenant_id, total_charge_cents, paid_amount_cents, adjustment_amount_cents, open_balance_cents, last_calculated_at) values (p_claim_id, v_tenant_id, coalesce(v_total,0), v_paid, v_adj, coalesce(v_total,0) - v_paid - v_adj, now()) on conflict (claim_id) do update set total_charge_cents = excluded.total_charge_cents, paid_amount_cents = excluded.paid_amount_cents, adjustment_amount_cents = excluded.adjustment_amount_cents, open_balance_cents = excluded.open_balance_cents, last_calculated_at = now(); end; $$;
create or replace function public.recalculate_client_balance_summary(p_client_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare v_tenant_id uuid; v_balance bigint; begin select tenant_id into v_tenant_id from public.clients where id = p_client_id; if v_tenant_id is null then return; end if; select coalesce(sum(case when side = 'debit' then amount_cents else -amount_cents end), 0) into v_balance from public.ledger_entries where client_id = p_client_id; insert into public.client_balance_summaries (client_id, tenant_id, open_balance_cents, credit_balance_cents, last_calculated_at) values (p_client_id, v_tenant_id, greatest(v_balance, 0), greatest(-v_balance, 0), now()) on conflict (client_id) do update set open_balance_cents = excluded.open_balance_cents, credit_balance_cents = excluded.credit_balance_cents, last_calculated_at = now(); end; $$;
create or replace function public.recalculate_balances_from_allocation() returns trigger language plpgsql security definer set search_path = public as $$ begin if coalesce(new.claim_id, old.claim_id) is not null then perform public.recalculate_claim_balance_summary(coalesce(new.claim_id, old.claim_id)); end if; if coalesce(new.client_id, old.client_id) is not null then perform public.recalculate_client_balance_summary(coalesce(new.client_id, old.client_id)); end if; return coalesce(new, old); end; $$;
create trigger trg_recalculate_claim_after_payment after insert or update or delete on payment_allocations for each row execute function public.recalculate_balances_from_allocation();
create trigger trg_recalculate_claim_after_adjustment after insert or update or delete on adjustment_allocations for each row execute function public.recalculate_balances_from_allocation();
create or replace function public.create_workqueue_history() returns trigger language plpgsql security definer set search_path = public, auth as $$ begin if tg_op = 'INSERT' then insert into public.workqueue_history (tenant_id, workqueue_item_id, new_status, new_priority, changed_by, note) values (new.tenant_id, new.id, new.workqueue_status, new.priority, (select auth.uid()), 'created'); elsif new.workqueue_status is distinct from old.workqueue_status or new.priority is distinct from old.priority then insert into public.workqueue_history (tenant_id, workqueue_item_id, old_status, new_status, old_priority, new_priority, changed_by) values (new.tenant_id, new.id, old.workqueue_status, new.workqueue_status, old.priority, new.priority, (select auth.uid())); end if; return new; end; $$;
create trigger trg_create_workqueue_history after insert or update on workqueue_items for each row execute function public.create_workqueue_history();

create index idx_tenant_users_user_tenant on tenant_users (user_id, tenant_id);
create index idx_tenant_user_roles_user_tenant on tenant_user_roles (user_id, tenant_id);
create index idx_audit_logs_target on audit_logs (target_type, target_id);
create index idx_audit_logs_tenant_created on audit_logs (tenant_id, created_at desc);
create index idx_clients_tenant_status on clients (tenant_id, client_status);
create index idx_clients_tenant_name on clients (tenant_id, last_name, first_name);
create index idx_clients_search_name on clients using gin (search_name gin_trgm_ops);
create index idx_client_insurance_client on client_insurance_policies (client_id);
create index idx_client_insurance_active_dates on client_insurance_policies (client_id, effective_date, termination_date);
create index idx_eligibility_checks_client_dos on eligibility_checks (client_id, service_date desc);
create index idx_providers_tenant_status on providers (tenant_id, provider_status);
create index idx_provider_enrollments_provider_payer on provider_payer_enrollments (provider_id, payer_id);
create index idx_appointments_tenant_start on appointments (tenant_id, starts_at);
create index idx_appointments_provider_start on appointments (provider_id, starts_at);
create index idx_appointments_client_start on appointments (client_id, starts_at desc);
create index idx_clinical_notes_client on clinical_notes (client_id, service_date desc);
create index idx_clinical_notes_status on clinical_notes (tenant_id, note_status);
create index idx_client_diagnoses_active on client_diagnoses (client_id, diagnosis_code) where diagnosis_status = 'active';
create index idx_charge_capture_tenant_status on charge_capture_items (tenant_id, charge_status);
create index idx_charge_capture_client on charge_capture_items (client_id, service_date desc);
create unique index uq_charge_capture_appointment on charge_capture_items (appointment_id) where appointment_id is not null and charge_status <> 'voided';
create index idx_claims_tenant_status on professional_claims (tenant_id, claim_status);
create index idx_claims_client on professional_claims (client_id, service_date_from desc);
create index idx_claims_payer on professional_claims (payer_id, service_date_from desc);
create index idx_claims_ready_for_batch on professional_claims (tenant_id, service_date_from) where claim_status = 'ready_for_batch';
create index idx_claims_open_ar on professional_claims (tenant_id, payer_id, service_date_from) where claim_status in ('submitted','accepted','denied','partially_paid');
create index idx_claim_lines_claim on professional_claim_lines (claim_id);
create index idx_claim_batch_items_claim on claim_batch_items (claim_id);
create index idx_payments_client on payments (client_id, payment_date desc);
create index idx_payments_payer on payments (payer_id, payment_date desc);
create index idx_payment_allocations_claim on payment_allocations (claim_id);
create index idx_payment_allocations_client on payment_allocations (client_id);
create index idx_adjustments_claim on adjustments (claim_id, adjustment_date desc);
create index idx_adjustment_allocations_claim on adjustment_allocations (claim_id);
create index idx_historical_transactions_client on historical_transactions (client_id, transaction_date desc);
create index idx_historical_transactions_tenant_status on historical_transactions (tenant_id, transaction_status);
create index idx_ledger_entries_client on ledger_entries (client_id, posting_date desc);
create index idx_ledger_entries_claim on ledger_entries (claim_id, posting_date desc);
create index idx_ledger_entries_tenant_posting_date on ledger_entries (tenant_id, posting_date desc);
create index idx_ledger_transactions_source on ledger_transactions (source_type, source_id);
create index idx_era_claims_claim_number on era_claims (payer_claim_number);
create index idx_era_matches_status on era_matches (tenant_id, match_status);
create index idx_denials_claim on denials (claim_id);
create index idx_denials_open on denials (tenant_id, denial_date desc) where denial_status not in ('resolved_paid','resolved_writeoff','closed');
create index idx_workqueue_open on workqueue_items (tenant_id, due_date, priority) where workqueue_status in ('open','in_progress','pending','snoozed','reopened');
create unique index uq_workqueue_open_source_type on workqueue_items (tenant_id, source_object_type, source_object_id, workqueue_type) where workqueue_status not in ('completed','cancelled');
create index idx_account_notes_client on account_notes (client_id, created_at desc);
create index idx_claim_notes_claim on claim_notes (claim_id, created_at desc);
create index idx_documents_client on documents (client_id, created_at desc);
create index idx_fee_schedule_lines_lookup on fee_schedule_lines (fee_schedule_id, cpt_code, modifier);
create index idx_notifications_user_created on notifications (user_id, created_at desc);

DO $$ declare r record; begin for r in select table_schema, table_name from information_schema.columns where table_schema = 'public' and column_name = 'updated_at' and table_name in (select table_name from information_schema.columns where table_schema = 'public' and column_name = 'created_at') loop execute format('create trigger trg_set_timestamps before insert or update on %I.%I for each row execute function public.set_timestamps()', r.table_schema, r.table_name); end loop; end $$;
DO $$ declare t text; begin foreach t in array array['clients','client_contacts','client_insurance_policies','eligibility_checks','providers','provider_payer_enrollments','appointments','client_checkins','clinical_notes','treatment_plans','charge_capture_items','professional_claims','payments','payment_allocations','adjustments','adjustment_allocations','historical_transactions','ledger_transactions','ledger_entries','era_files','era_claims','denials','appeals','workqueue_items','account_notes','claim_notes','documents','payer_contracts','fee_schedules'] loop execute format('create trigger trg_audit_row_changes after insert or update or delete on public.%I for each row execute function public.audit_row_change()', t); end loop; end $$;

DO $$ declare r record; begin for r in select tablename from pg_tables where schemaname = 'public' loop execute format('alter table public.%I enable row level security', r.tablename); end loop; end $$;

create policy "users can read own profile" on user_profiles for select to authenticated using (id = (select auth.uid()));
create policy "users can update own profile" on user_profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "users can insert own profile" on user_profiles for insert to authenticated with check (id = (select auth.uid()));
create policy "users can read own tenant memberships" on tenant_users for select to authenticated using (user_id = (select auth.uid()));
create policy "users can read own tenant roles" on tenant_user_roles for select to authenticated using (user_id = (select auth.uid()));
create policy "members can read tenants" on tenants for select to authenticated using (exists (select 1 from tenant_users tu where tu.tenant_id = tenants.id and tu.user_id = (select auth.uid()) and tu.status = 'active'));
create policy "authenticated can read payer reference" on payers for select to authenticated using (true);
create policy "authenticated can read payer plan reference" on payer_plans for select to authenticated using (true);
create policy "authenticated can read payer aliases" on payer_aliases for select to authenticated using (true);

DO $$ declare r record; begin for r in select c.table_schema, c.table_name from information_schema.columns c where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenant_users','tenant_user_roles','tenants','audit_logs','system_events','phi_access_logs','payers','payer_plans','payer_aliases') loop execute format('create policy %I on %I.%I for select to authenticated using (public.is_tenant_member(tenant_id))', r.table_name || ' tenant select', r.table_schema, r.table_name); execute format('create policy %I on %I.%I for insert to authenticated with check (public.is_tenant_member(tenant_id))', r.table_name || ' tenant insert', r.table_schema, r.table_name); execute format('create policy %I on %I.%I for update to authenticated using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id))', r.table_name || ' tenant update', r.table_schema, r.table_name); end loop; end $$;

create policy "members can read audit logs" on audit_logs for select to authenticated using (tenant_id is not null and public.is_tenant_member(tenant_id));
create policy "members can read system events" on system_events for select to authenticated using (tenant_id is not null and public.is_tenant_member(tenant_id));
create policy "members can read phi access logs" on phi_access_logs for select to authenticated using (tenant_id is not null and public.is_tenant_member(tenant_id));
create policy "users can read own notifications" on notifications for select to authenticated using (user_id = (select auth.uid()));
create policy "users can update own notifications" on notifications for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

revoke all on all tables in schema public from anon;
revoke execute on all functions in schema public from anon;
grant usage on schema public to authenticated;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to authenticated;
grant execute on all functions in schema public to authenticated;
alter default privileges in schema public revoke select, insert, update, delete on tables from anon;
alter default privileges in schema public revoke execute on functions from anon;
alter default privileges in schema public grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public grant usage, select on sequences to authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('therassistant-documents','therassistant-documents',false,52428800,array['application/pdf','image/jpeg','image/png','image/webp','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict (id) do nothing;
